{{-- $liveVersion, $liveRegionUrl, $liveVersionUrl, optional $liveStatsUrl. Same design as the Workstation pages: polls every 15 s, pauses while the tab is hidden, checks at once when it is visible again, and can be paused by hand. --}}
<div id="wca-live" hidden data-version="{{ $liveVersion }}" data-version-url="{{ $liveVersionUrl }}" data-region-url="{{ $liveRegionUrl }}" @if (! empty($liveStatsUrl)) data-stats-url="{{ $liveStatsUrl }}" @endif data-interval="15000"></div>
<p class="wca-live-note"><span class="wca-dot is-green" id="wca-live-dot" aria-hidden="true"></span><span id="wca-live-status" aria-live="polite">Live &middot; updated {{ now('Asia/Kuala_Lumpur')->format('H:i:s') }}</span> <button type="button" class="wca-link-btn" id="wca-live-pause">Pause updates</button></p>
